/// As above, but the kill waits until `ready(markers)` as well — used to catch a sandbox once its byte copy has
/// been populated rather than at the instant the marker is written.
fn spawn_and_kill_when(
    root: &Path,
    state_of: &Path,
    session: &str,
    args: &[&str],
    ready: impl Fn(&[String]) -> bool,
) -> (Vec<String>, usize) {
    const MAX_POLLS: usize = 120_000; // 1 ms each => 120 s ceiling, never reached in practice
    let mut c = std::process::Command::new(gov_bin());
    c.arg("--json")
        .arg("--root")
        .arg(root)
        .arg("--session")
        .arg(session)
        .arg("--role")
        .arg("orchestrator")
        .args(args)
        .env("GOV_CANONICAL_ROOT", canonical_root())
        .env("XDG_STATE_HOME", machine_state_home(state_of))
        .env_remove("GOV_SESSION")
        .env_remove("GOV_ROLE")
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null());
    let mut child = c.spawn().expect("spawn gov");
    let mut seen: Vec<String> = vec![];
    let mut polls = 0usize;
    while polls < MAX_POLLS {
        let m = sandbox_markers(state_of);
        if !m.is_empty() && ready(&m) {
            seen = m;
            break;
        }
        // deterministic exit if the command finished without our ever observing a live marker
        if let Ok(Some(_)) = child.try_wait() {
            break;
        }
        std::thread::sleep(std::time::Duration::from_millis(1));
        polls += 1;
    }
    let _ = child.kill(); // SIGKILL: no unwinding, no Drop, no cleanup
    let _ = child.wait();
    (seen, polls)
}

